//! Actual shared persistence, OS locks and generated bytes, without CFAPI or
//! provider accounts. The child exits without Rust destructors to model a crash.
use sha2::{Digest, Sha256};
use std::{
    fs::{self, File},
    io::{Read, Seek, SeekFrom, Write},
    path::{Path, PathBuf},
    process::Command,
};
use twodrive_core::{CacheJournal, Database, FileState, MetadataEntry};
const ID: &str = "generated-opaque-id";
const ORIGINAL: &[u8] = b"generated acknowledged bytes";
const EDITED: &[u8] = b"generated unuploaded edited bytes, preserved in full";
fn digest(file: &mut File) -> anyhow::Result<String> {
    file.seek(SeekFrom::Start(0))?;
    let mut hash = Sha256::new();
    let mut bytes = [0; 4096];
    loop {
        let count = file.read(&mut bytes)?;
        if count == 0 {
            break;
        }
        hash.update(&bytes[..count]);
    }
    Ok(format!("{:x}", hash.finalize()))
}
fn hash(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}
fn paths(root: &Path) -> (Database, PathBuf, PathBuf) {
    let root = root.canonicalize().unwrap();
    let cache = root.join("cache");
    fs::create_dir_all(&cache).unwrap();
    (
        Database::new(root.join("fixture.sqlite3")),
        cache.clone(),
        cache.join("generated-缓存.bin"),
    )
}
fn fixture() -> (tempfile::TempDir, CacheJournal, PathBuf) {
    let temp = tempfile::tempdir().unwrap();
    let (db, root, path) = paths(temp.path());
    db.init().unwrap();
    db.upsert_metadata(&MetadataEntry::new_file(
        ID,
        "/generated.txt",
        ORIGINAL.len() as u64,
        1,
        "version-1",
    ))
    .unwrap();
    fs::write(&path, ORIGINAL).unwrap();
    let journal = CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).unwrap();
    journal
        .publish_download(ID, 0, &path, &hash(ORIGINAL), "version-1")
        .unwrap();
    (temp, journal, path)
}
fn edit(j: &CacheJournal) {
    let mut writer = j.open_write(ID).unwrap();
    writer.set_len(0).unwrap();
    writer.write_all(EDITED).unwrap();
    writer.finish().unwrap();
}
fn receipt() -> MetadataEntry {
    MetadataEntry::new_file(ID, "/generated.txt", EDITED.len() as u64, 2, "version-2")
}

#[test]
fn writer_intent_precedes_mutation_and_stale_cached_is_not_clean() {
    let (_temp, j, path) = fixture();
    let mut writer = j.open_write(ID).unwrap();
    let state = j.snapshot(ID).unwrap();
    assert_eq!(state.state, FileState::Writing);
    assert_eq!(state.generation, 1);
    assert!(state.dirty_intent);
    assert_eq!(state.writers, 1);
    writer.set_len(0).unwrap();
    writer.write_all(EDITED).unwrap();
    writer.finish().unwrap();
    j.database().mark_state(ID, FileState::Cached).unwrap();
    assert!(!j.snapshot(ID).unwrap().engine_release_ready());
    assert!(
        j.with_clean_cache::<()>(ID, 1, |_, _| {
            panic!("dirty cache must never enter release action")
        })
        .unwrap()
        .is_none()
    );
    assert_eq!(fs::read(path).unwrap(), EDITED);
}

#[test]
fn legacy_release_cannot_bypass_native_journal_with_a_stale_cached_label() {
    let (_temp, j, path) = fixture();
    edit(&j);
    j.database().mark_state(ID, FileState::Cached).unwrap();
    let stale = j.database().get_by_remote_id(ID).unwrap().unwrap();
    assert!(
        !j.database().release_record(&stale).unwrap(),
        "legacy release must defer to the native journal"
    );
    assert_eq!(fs::read(path).unwrap(), EDITED);
}
#[test]
fn actual_reader_and_owner_locks_block_competing_writes_and_release() {
    let (temp, j, _) = fixture();
    let reader = j.open_read(ID).unwrap();
    assert_eq!(j.snapshot(ID).unwrap().readers, 1);
    assert!(j.open_write(ID).is_err());
    assert!(j.with_clean_cache(ID, 0, |_, _| Ok(())).unwrap().is_none());
    let (db, root, _) = paths(temp.path());
    assert!(CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).is_err());
    drop(reader);
    assert_eq!(j.snapshot(ID).unwrap().readers, 0);
    assert!(
        j.with_clean_cache(ID, 0, |file, expected| Ok(digest(file)? == expected))
            .unwrap()
            .unwrap()
    );
}
#[test]
fn upload_queue_and_lost_reply_are_durable_release_vetoes() {
    let (_temp, j, path) = fixture();
    edit(&j);
    let lease = j.begin_upload(ID, digest).unwrap();
    assert_eq!(j.snapshot(ID).unwrap().upload_generation, Some(1));
    assert!(j.open_write(ID).is_err());
    assert!(j.with_clean_cache(ID, 1, |_, _| Ok(())).unwrap().is_none());
    drop(lease);
    assert!(j.snapshot(ID).unwrap().uncertain_upload);
    assert!(j.begin_upload(ID, digest).is_err());
    assert_eq!(fs::read(path).unwrap(), EDITED);
}
#[test]
fn only_current_generation_and_verified_receipt_can_acknowledge() {
    let (_temp, j, _) = fixture();
    edit(&j);
    let lease = j.begin_upload(ID, digest).unwrap();
    assert!(lease.acknowledge(&receipt(), &hash(EDITED)).unwrap());
    let state = j.snapshot(ID).unwrap();
    assert_eq!(state.generation, state.acknowledged_generation);
    assert_eq!(state.state, FileState::Cached);
    assert!(j.with_clean_cache(ID, 0, |_, _| Ok(())).unwrap().is_none());
    assert!(
        j.with_clean_cache(ID, 1, |file, expected| Ok(digest(file)? == expected))
            .unwrap()
            .unwrap()
    );
    edit(&j);
    let lease = j.begin_upload(ID, digest).unwrap();
    j.database().mark_state(ID, FileState::Dirty).unwrap();
    assert!(!lease.acknowledge(&receipt(), &hash(EDITED)).unwrap());
    assert!(j.snapshot(ID).unwrap().uncertain_upload);
}
#[test]
fn pending_delete_and_parent_move_veto_release() {
    let (_temp, j, path) = fixture();
    j.database()
        .queue_remote_delete(ID, "/generated.txt")
        .unwrap();
    assert!(j.snapshot(ID).unwrap().pending_operations);
    assert!(j.with_clean_cache(ID, 0, |_, _| Ok(())).unwrap().is_none());
    assert_eq!(fs::read(path).unwrap(), ORIGINAL);
    let (_temp, j, _) = fixture();
    j.database()
        .upsert_metadata(&MetadataEntry::new_dir("parent", "/", 1, "parent-v1"))
        .unwrap();
    j.database()
        .move_subtree_and_queue("parent", "/moved")
        .unwrap();
    assert!(j.snapshot(ID).unwrap().pending_operations);
    assert!(!j.snapshot(ID).unwrap().engine_release_ready());
}
#[test]
fn out_of_band_version_or_cache_binding_change_fails_closed() {
    let (_temp, j, _) = fixture();
    let entry = MetadataEntry::new_file(
        ID,
        "/generated.txt",
        ORIGINAL.len() as u64,
        2,
        "unexpected-new-version",
    );
    j.database().upsert_metadata(&entry).unwrap();
    assert!(j.snapshot(ID).unwrap().pending_operations);
    assert!(!j.snapshot(ID).unwrap().engine_release_ready());
    let (_temp, j, path) = fixture();
    let other = path.with_file_name("generated-replacement.bin");
    fs::write(&other, ORIGINAL).unwrap();
    j.database().mark_cached(ID, &other).unwrap();
    assert!(j.snapshot(ID).unwrap().pending_operations);
    assert!(j.with_clean_cache(ID, 0, |_, _| Ok(())).unwrap().is_none());
    assert_eq!(fs::read(path).unwrap(), ORIGINAL);
}

#[test]
fn unknown_journal_schema_is_refused_without_recovery_mutation() {
    let (temp, j, path) = fixture();
    j.database()
        .set_state_value("local_cache_schema", "999")
        .unwrap();
    drop(j);
    let (db, root, _) = paths(temp.path());
    assert!(CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).is_err());
    assert_eq!(fs::read(path).unwrap(), ORIGINAL);
}

#[test]
fn native_dirty_bytes_remain_a_durable_veto_across_restart() {
    let (temp, j, path) = fixture();
    j.record_native_edit(ID).unwrap();
    j.record_native_edit(ID).unwrap();
    let state = j.snapshot(ID).unwrap();
    assert!(state.native_dirty && state.recovery_required);
    assert_eq!(state.generation, 1);
    assert_eq!(state.state, FileState::Dirty);
    assert!(j.open_read(ID).is_err());
    assert!(j.open_write(ID).is_err());
    assert!(j.recover_write(ID).is_err());
    assert!(j.begin_upload(ID, digest).is_err());
    assert!(!state.engine_release_ready());
    drop(j);
    let (db, root, _) = paths(temp.path());
    let reopened = CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).unwrap();
    assert!(reopened.snapshot(ID).unwrap().native_dirty);
    assert!(reopened.recover_write(ID).is_err());
    assert_eq!(fs::read(path).unwrap(), ORIGINAL);
}

#[test]
fn native_edit_before_first_hydration_blocks_metadata_claim() {
    let temp = tempfile::tempdir().unwrap();
    let (db, root, _) = paths(temp.path());
    let journal = CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).unwrap();
    journal.record_native_edit(ID).unwrap();
    assert!(journal.begin_download(&receipt()).is_err());
    assert!(
        journal
            .database()
            .get_by_cloud_remote_id(ID)
            .unwrap()
            .is_none()
    );
}

#[test]
fn concurrent_writer_has_one_durable_lease_and_blocks_other_access() {
    let (_temp, j, path) = fixture();
    let barrier = std::sync::Arc::new(std::sync::Barrier::new(2));
    let peer = j.clone();
    let sync = barrier.clone();
    let worker = std::thread::spawn(move || {
        let mut writer = peer.open_write(ID).unwrap();
        sync.wait();
        sync.wait();
        writer.set_len(0).unwrap();
        writer.write_all(EDITED).unwrap();
        writer.finish().unwrap();
    });
    barrier.wait();
    assert_eq!(j.snapshot(ID).unwrap().writers, 1);
    assert!(j.open_read(ID).is_err());
    assert!(j.open_write(ID).is_err());
    assert!(j.with_clean_cache(ID, 1, |_, _| Ok(())).unwrap().is_none());
    barrier.wait();
    worker.join().unwrap();
    assert_eq!(j.snapshot(ID).unwrap().writers, 0);
    assert_eq!(fs::read(path).unwrap(), EDITED);
}

#[test]
fn external_os_file_lock_is_a_veto_even_without_a_journal_reader_count() {
    let (_temp, j, path) = fixture();
    let file = File::open(&path).unwrap();
    file.lock_shared().unwrap();
    assert_eq!(j.snapshot(ID).unwrap().readers, 0);
    assert!(j.with_clean_cache(ID, 0, |_, _| Ok(())).unwrap().is_none());
    drop(file);
    assert!(
        j.with_clean_cache(ID, 0, |file, expected| Ok(digest(file)? == expected))
            .unwrap()
            .unwrap()
    );
}

#[test]
fn reconciliation_must_rehash_inside_the_final_cache_lease() {
    let (_temp, j, path) = fixture();
    edit(&j);
    drop(j.begin_upload(ID, digest).unwrap());
    let mut reader = j.open_read(ID).unwrap();
    let mut observed = Vec::new();
    reader.read_to_end(&mut observed).unwrap();
    let stale_digest = hash(&observed);
    drop(reader);
    let mut changed = EDITED.to_vec();
    changed[0] ^= 1;
    fs::write(&path, &changed).unwrap();
    assert_ne!(stale_digest, hash(&changed));
    assert!(
        !j.reconcile_upload(ID, &receipt(), &hash(EDITED), digest)
            .unwrap(),
        "stale pre-lock digest must not acknowledge changed bytes"
    );
    assert_ne!(
        j.snapshot(ID).unwrap().generation,
        j.snapshot(ID).unwrap().acknowledged_generation
    );
    assert_eq!(fs::read(path).unwrap(), changed);
}
#[test]
fn uncertain_upload_reconciles_full_content_not_metadata_alone() {
    let (_temp, j, _) = fixture();
    edit(&j);
    drop(j.begin_upload(ID, digest).unwrap());
    let remote = receipt();
    assert!(
        j.reconcile_upload(ID, &remote, &hash(EDITED), digest)
            .unwrap()
    );
    assert!(j.snapshot(ID).unwrap().engine_release_ready());
    edit(&j);
    drop(j.begin_upload(ID, digest).unwrap());
    let remote = MetadataEntry::new_file(ID, "/generated.txt", 3, 3, "conflicting-version");
    assert!(
        !j.reconcile_upload(ID, &remote, &hash(b"different remote"), digest)
            .unwrap()
    );
    assert_eq!(j.snapshot(ID).unwrap().state, FileState::Conflict);
}
#[test]
fn crash_child() {
    let Ok(root) = std::env::var("TWODRIVE_JOURNAL_CHILD_ROOT") else {
        return;
    };
    let (db, cache, _) = paths(Path::new(&root));
    let j = CacheJournal::open(db, &cache, &hash(b"generated-provider-binding")).unwrap();
    if std::env::var("TWODRIVE_JOURNAL_CHILD_MODE").unwrap() == "write" {
        let mut writer = j.open_write(ID).unwrap();
        writer.set_len(0).unwrap();
        writer.write_all(EDITED).unwrap();
        writer.sync_all().unwrap();
        std::process::exit(0);
    }
    let _lease = j.begin_upload(ID, digest).unwrap();
    std::process::exit(0);
}
fn child(root: &Path, mode: &str) {
    let status = Command::new(std::env::current_exe().unwrap())
        .args(["--exact", "crash_child", "--nocapture"])
        .env("TWODRIVE_JOURNAL_CHILD_ROOT", root)
        .env("TWODRIVE_JOURNAL_CHILD_MODE", mode)
        .status()
        .unwrap();
    assert!(status.success());
}
#[test]
fn process_restart_preserves_unclosed_write_and_requires_recovery() {
    let (temp, j, path) = fixture();
    drop(j);
    child(temp.path(), "write");
    let (db, root, _) = paths(temp.path());
    let j = CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).unwrap();
    let state = j.snapshot(ID).unwrap();
    assert_eq!(state.state, FileState::Dirty);
    assert!(state.recovery_required);
    assert!(state.dirty_intent);
    assert_eq!(state.writers, 0);
    assert_eq!(fs::read(&path).unwrap(), EDITED);
    assert!(j.begin_upload(ID, digest).is_err());
    j.recover_write(ID).unwrap();
    assert_eq!(fs::read(path).unwrap(), EDITED);
    assert!(!j.snapshot(ID).unwrap().recovery_required);
}
#[test]
fn process_restart_keeps_ambiguous_upload_and_rejects_blind_retry() {
    let (temp, j, path) = fixture();
    edit(&j);
    drop(j);
    child(temp.path(), "upload");
    let (db, root, _) = paths(temp.path());
    let j = CacheJournal::open(db, &root, &hash(b"generated-provider-binding")).unwrap();
    assert!(j.snapshot(ID).unwrap().uncertain_upload);
    assert!(j.begin_upload(ID, digest).is_err());
    assert!(!j.snapshot(ID).unwrap().engine_release_ready());
    assert_eq!(fs::read(path).unwrap(), EDITED);
    assert!(
        j.reconcile_upload(ID, &receipt(), &hash(EDITED), digest)
            .unwrap()
    );
}
